def elevatorRequests(n, start, requests):
    # For every distinct floor keep only the latest arrival (the binding one)
    latest = {}
    for arrival, floor in requests:
        if floor not in latest or arrival > latest[floor]:
            latest[floor] = arrival
    floors = sorted(latest)
    m = len(floors)
    arr = [latest[f] for f in floors]
    INF = float("inf")

    # L[l][r]: min time when requests outside [l, r] are all finalized and the last
    #          finalized one was floors[l - 1] (elevator stands there)
    # R[l][r]: same, but the last finalized one was floors[r + 1]
    # The LAST visits happen from the outside in, so we peel off either the lowest or
    # the highest remaining floor each step.
    L = [[INF] * m for _ in range(m)]
    R = [[INF] * m for _ in range(m)]
    best = INF

    def relax_from(l, r, t, pos):
        # elevator at pos at time t, interval [l, r] still pending
        nonlocal best
        # finalize the lowest pending floor
        t1 = max(t + abs(pos - floors[l]), arr[l])
        if l == r:
            best = min(best, t1)
        else:
            if t1 < L[l + 1][r]:
                L[l + 1][r] = t1
        # finalize the highest pending floor
        t2 = max(t + abs(pos - floors[r]), arr[r])
        if l == r:
            best = min(best, t2)
        else:
            if t2 < R[l][r - 1]:
                R[l][r - 1] = t2

    # start: nothing finalized, elevator at `start` at time 0
    relax_from(0, m - 1, 0, start)
    # shrink the interval one floor at a time (length m-1 down to 1)
    for length in range(m - 1, 0, -1):
        for l in range(0, m - length + 1):
            r = l + length - 1
            if L[l][r] < INF:
                relax_from(l, r, L[l][r], floors[l - 1])
            if R[l][r] < INF:
                relax_from(l, r, R[l][r], floors[r + 1])
    return best
